using UnityEngine;
namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        private System.Text.StringBuilder _stringBuffer;

        private void Awake()
        {
            _stringBuffer = new System.Text.StringBuilder(256);
        }

        private void Update()
        {
            _stringBuffer.Clear();
            _stringBuffer.Append("Status do Sistema: Otimizado sem alocação de GC");
        }
    }
}
